// Decimator's bounded, no-goal run. Reuse the contract-parity engine and check every logged peak.
import { AbiCoder, id, keccak256 } from '../vendor/ethers-app.mjs';
import { boardFrom, scatterInto, shooterBoostTerms, settleSlip, createSlipTrace, LEG_ORDER } from '../chain/craps-engine.js';
import { replayCrapsSoloRun } from './replay-engine.js';

export const DECIMATOR_BANKROLL = 3_000n * 10n ** 18n;
const WEI = 10n ** 18n;
const coder = AbiCoder.defaultAbiCoder();
const hash = (tag, types, values) => keccak256(coder.encode(['bytes32', ...types], [id(tag), ...values]));

export function replayDecimatorEntry(snapshot, entry) {
  const word = BigInt(snapshot.rngWord); const level = Number(snapshot.level); const entryId = BigInt(entry.entryId);
  const seed = hash('decimator.battle.dice.v1', ['uint256', 'uint24'], [word, level]);
  const boardWord = hash('decimator.battle.board.v1', ['uint256', 'uint24', 'uint64'], [word, level, entryId]);
  const player = entry.generated
    ? `0x${hash('decimator.battle.generated.player.v1', ['uint256', 'uint24', 'uint64'], [word, level, entryId]).slice(-40)}`
    : entry.address;
  const packed = BigInt(entry.chips);
  const named = LEG_ORDER.reduce((total, _, i) => total + ((packed >> BigInt(i * 3)) & 7n), 0n);
  const board = boardFrom(packed, 60n);
  scatterInto(board, BigInt(boardWord), 60n, 10n - named);
  const trace = createSlipTrace();
  const run = settleSlip(board, seed, DECIMATOR_BANKROLL, 0n, 48n, 511n, player, shooterBoostTerms(named), trace);
  if (entry.peak != null && run.peakBankroll !== BigInt(entry.peak)) throw new Error(`Entry ${entry.entryId}: peak mismatch`);
  const visual = replayCrapsSoloRun({
    betId: entry.entryId, player, boardWei: Object.fromEntries(LEG_ORDER.map(leg => [leg, board[leg] * WEI])),
    hands: trace.hands.map(hand => hand.map(roll => [roll.d1, roll.d2])),
    ladderWei: run.ladder.map(String), handsPlayed: run.handsPlayed, totalRolls: run.totalRolls,
    stop: 'bust', survivals: trace.survivals, boosts: trace.boosts,
  });
  let peak = DECIMATOR_BANKROLL;
  const scoreAt = value => entry.generated
    // Generated scores floor in the contract's whole-token stack units BEFORE normalization.
    ? (BigInt(snapshot.generatedStackTotal) / WEI * value / BigInt(snapshot.generatedStackCount)) * WEI
    : BigInt(entry.stack) * value;
  const point = bankroll => ({ bankroll: String(bankroll), peak: String(peak),
    score: String(scoreAt(peak) / DECIMATOR_BANKROLL), rankScore: String(scoreAt(peak)) });
  const checkpoints = [point(DECIMATOR_BANKROLL)];
  for (const hand of visual.hands) {
    const banked = BigInt(hand.bankrollAfterWei);
    if (banked > peak) peak = banked;
    checkpoints.push(point(hand.shooter === run.handsPlayed - 1 ? run.bankrollOut : banked));
  }
  if (peak !== run.peakBankroll) throw new Error(`Entry ${entry.entryId}: checkpoint mismatch`);
  if (entry.rankScore != null && scoreAt(peak) !== BigInt(entry.rankScore)) throw new Error(`Entry ${entry.entryId}: score mismatch`);
  return { ...entry, checkpoints, handsPlayed: run.handsPlayed, totalRolls: run.totalRolls,
    resolutionFrames: visual.events.map(event => {
      const handEnd = event === visual.hands[event.shooter].events.at(-1);
      const nextSurvival = handEnd ? visual.hands[event.shooter + 1]?.survival ? { survived: true }
        : visual.failedSurvival?.shooter === event.shooter + 1 ? { survived: false } : null : null;
      return { dice: [event.d1, event.d2], shooter: event.shooter,
        bankrollFlip: String(BigInt(event.bankrollAfterWei) / WEI),
        startingBankrollFlip: String(BigInt(event.bankrollBeforeWei) / WEI),
        deltaFlip: String(BigInt(event.deltaWei) / WEI), returnedFlip: String(BigInt(event.returnedWei) / WEI),
        boostFlip: String(BigInt(event.boostWei) / WEI), label: event.label, point: event.pointAfter || null,
        payoutBets: event.payoutBets, lostBets: event.lostBets, retiredBets: event.retiredBets,
        shooterBoost: event.shooterBoost, survival: nextSurvival,
        hotShooterActive: event.shooterBoost?.hotActive === true,
        viewerTerminal: event.terminal,
      };
    }),
    stop: run.handsPlayed === 48 || run.totalRolls === 511 ? 'capped' : 'bust',
    board: LEG_ORDER.map(leg => Number(board[leg] / 60n)),
    hands: trace.hands, boosts: trace.boosts, survivals: trace.survivals,
    peak: String(run.peakBankroll), score: checkpoints.at(-1).score, rankScore: checkpoints.at(-1).rankScore,
  };
}

export function buildDecimatorReplay(snapshot) {
  if (!snapshot.ranked) throw new Error('The field is still settling.');
  if ((snapshot.battleEntries ?? []).filter(entry => !entry.generated).length !== snapshot.entrants) {
    throw new Error('The complete entry field is not available yet.');
  }
  const eligible = (snapshot.battleEntries ?? []).filter(entry => entry.eligible);
  if (snapshot.survivorCount == null || eligible.length !== snapshot.survivorCount || eligible.some(entry => entry.peak == null)) {
    throw new Error('The complete survivor field is not available yet.');
  }
  let longest = [];
  const entries = eligible.map(entry => {
    const run = replayDecimatorEntry(snapshot, entry);
    if (run.hands.length > longest.length) longest = run.hands;
    const { hands, ...result } = run;
    return result;
  });
  let completedHands = 0;
  const frames = longest.flatMap((hand, shooter) => {
    let point = 0;
    return hand.map((roll, index) => {
      const before = point;
      const sevenOut = before !== 0 && roll.total === 7;
      if (!before && [4, 5, 6, 8, 9, 10].includes(roll.total)) point = roll.total;
      else if (roll.total === before || sevenOut) point = 0;
      const handEnd = index === hand.length - 1;
      if (handEnd) completedHands++;
      return { ...roll, shooter, rollInHand: index + 1, point, handEnd, completedHands,
        label: sevenOut ? 'SEVEN OUT' : before && roll.total === before ? 'POINT MADE'
          : !before && point ? `POINT ${point}` : `${roll.total} ROLLED` };
    });
  });
  return { entries, frames };
}

/** Cancelable worker: closing the takeover also stops expensive field verification. */
export function prepareDecimatorReplay(snapshot, { signal } = {}) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) { reject(new Error('Replay canceled.')); return; }
    const worker = new Worker(new URL('./decimator-worker.js?v=decimator-skin-20261006', import.meta.url), { type: 'module' });
    let timeout;
    const finish = (error, replay) => {
      clearTimeout(timeout); signal?.removeEventListener('abort', cancel); worker.terminate();
      if (error) reject(error); else resolve(replay);
    };
    const cancel = () => finish(new Error('Replay canceled.'));
    signal?.addEventListener('abort', cancel, { once: true });
    worker.onmessage = ({ data }) => finish(data.error ? new Error(data.error) : null, data.replay);
    worker.onerror = () => finish(new Error('Replay could not be verified.'));
    timeout = setTimeout(() => finish(new Error('Replay verification took too long.')), 45_000);
    worker.postMessage(snapshot);
  });
}
